def solution(*args, **kwargs):
    import sys

    # Support both direct argument call and stdin (as in the problem statement)
    if args:
        x = int(args[0])
    else:
        data = sys.stdin.read().strip()
        if not data:
            return
        x = int(data)

    x_str = str(x)
    n = len(x_str)

    # Initial best is x itself
    def digit_sum(num: int) -> int:
        s = 0
        while num:
            s += num % 10
            num //= 10
        return s

    best = x
    best_sum = digit_sum(x)

    def update(candidate: int):
        nonlocal best, best_sum
        if candidate <= 0 or candidate > x:
            return
        ds = digit_sum(candidate)
        if ds < best_sum or (ds == best_sum and candidate < best):
            best_sum = ds
            best = candidate

    s = x_str

    # Consider candidates by decreasing a prefix and filling the rest with 9s
    for i in range(n):
        if s[i] == '0':
            continue

        prefix = list(s[: i + 1])

        # Subtract 1 from this prefix
        j = i
        while j >= 0:
            if prefix[j] > '0':
                prefix[j] = chr(ord(prefix[j]) - 1)
                break
            else:
                prefix[j] = '9'
                j -= 1

        if j < 0 or prefix[0] == '0':
            continue

        cand_str = ''.join(prefix) + '9' * (n - i - 1)
        cand = int(cand_str)
        update(cand)

    # Also explicitly consider numbers consisting only of 9s with fewer digits
    for k in range(1, n):
        cand = int('9' * k)
        update(cand)

    # Return for direct call; print for stdin usage
    if args:
        return best
    else:
        print(best)
